    {
      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/disease-vaccination-viz#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "How many measles cases have there been in the U.S. in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "States reported 5,073 measles cases to CDC in 2026 through November 7, or 1.48 per 100,000 residents. That is the most in any year since 1991. The count is provisional, and final counts are usually higher."
          }
        },
        {
          "@type": "Question",
          "name": "Do states with lower vaccination rates have more measles?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "This map puts vaccination and cases side by side. It does not test whether one causes the other, and many other things affect where measles spreads. In 2026, through November 7, 13 of the 38 states and DC where fewer than 95% of kindergartners had the measles vaccine reported more than 1 measles case per 100,000 residents. Of the 10 states at 95% or more, one did: New York. CDC says one dose of the MMR vaccine is 93% effective against measles and two doses are 97% effective."
          }
        },
        {
          "@type": "Question",
          "name": "Which states have the highest measles rates in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Through November 7, Utah (15.03 cases per 100,000 residents), South Carolina (12.32) and Pennsylvania (11.30)."
          }
        },
        {
          "@type": "Question",
          "name": "Can I see measles cases by county?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, for 2025 and 2026. Click a state to see a circle on each county with confirmed measles cases, from the Johns Hopkins measles tracking team, along with county kindergarten vaccination rates where the state publishes them. County counts are not available for earlier years."
          }
        },
        {
          "@type": "Question",
          "name": "Which counties have the most measles cases in 2026?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Through November 6, the Johns Hopkins measles tracking team counts the most cases in Spartanburg County, South Carolina (610), Lancaster County, Pennsylvania (508), Mifflin County, Pennsylvania (205), Grant County, Wisconsin (137) and Hudspeth County, Texas (136). Its counts come from different reports than CDC's, so its totals differ."
          }
        },
        {
          "@type": "Question",
          "name": "What share of kindergartners have the measles vaccine?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In the 2025-26 school year, 92.4% of kindergartners in the U.S. had the measles vaccine (MMR). In 38 states and DC, the share was below 95%."
          }
        },
        {
          "@type": "Question",
          "name": "Which states have the lowest kindergarten measles vaccination rates?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In the 2025-26 school year, Idaho (75.2%), Wisconsin (85.1%) and Minnesota (85.7%)."
          }
        },
        {
          "@type": "Question",
          "name": "Why is 95% the line between green and amber?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "95% is the national Healthy People 2030 target for kindergartners with the measles vaccine. The map uses the same level for the whooping cough and polio vaccines so the colors can be compared."
          }
        },
        {
          "@type": "Question",
          "name": "Why is the top-left half of every state white before 2010?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CDC's state kindergarten figures start with the 2009-10 school year. Before that there is no state figure to show."
          }
        },
        {
          "@type": "Question",
          "name": "Why is there no vaccination color for hepatitis A?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CDC's state kindergarten figures do not include the hepatitis A vaccine. Toddler figures for it are in the vaccination chart beside the map."
          }
        },
        {
          "@type": "Question",
          "name": "Where does the data come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Case counts come from the U.S. Public Health Service's yearly tables (1920 to 1955), CDC's yearly and weekly tables (1956 to 2026) and Project Tycho. Vaccination figures come from CDC's SchoolVaxView and National Immunization Survey."
          }
        },
        {
          "@type": "Question",
          "name": "Is the map free to use?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. It is free to use and needs no sign-in."
          }
        }
